-- New service: Jump Starter Service (car & bike). Run once on every environment (local + live).
-- The home page, header menu, /services page, image sitemap and service page all read the `service`
-- table, so this single row publishes it everywhere. Replace the image from Admin > Services if needed.
SET NAMES utf8mb4;

INSERT INTO `service`
  (`token`, `service_name`, `service_img`, `short_description`, `description`,
   `card1_title`, `card1_description`, `card2_title`, `card2_description`,
   `process_steps`, `faqs`, `status`, `delete_status`, `created_by`)
SELECT
  'jump-starter-service',
  'Jump Starter Service - Car & Bike',
  'themes/images/service-image-10.jpg',
  'Car and bike jump starter service in Coimbatore when your vehicle battery goes flat. Our technician reaches your home, office, parking area or roadside Monday to Saturday, 9AM to 10PM to get you started and advise on battery testing, charging or replacement.',
  'Kiara Battery Clinic provides jump starter service for cars and bikes in Coimbatore - including Tatabad, Gandhipuram, RS Puram, Peelamedu and Saravanampatti - with coverage on request in Ooty, Kotagiri, Pollachi and Tiruppur. If your vehicle will not start because of a discharged battery at home, in a parking area, at your workplace or on the roadside, our technician comes to you Monday to Saturday, 9AM to 10PM. For calls within Coimbatore city, a technician typically arrives within 30-60 minutes.\n\nWe assist with vehicle battery jump-starting using suitable equipment and recommended safety procedures. Before starting the vehicle, the battery condition and compatibility are checked to decide whether jump-starting is appropriate. Our goal is a smooth service experience, fewer unnecessary delays and a vehicle that starts with confidence.\n\nWhether you need car jump-start assistance or bike battery starting support, our team assesses the issue and recommends the next step if the battery needs charging, testing or replacement - with genuine Amaron, Exide, SF Sonic and Okaya batteries available for doorstep fitting. Call or WhatsApp +91 90038 11107 to check jump starter service availability in your area.',
  'Fast Vehicle Starting Assistance',
  'A weak or discharged battery can interrupt your plans without warning. Our jump-start assistance helps get compatible cars and bikes started when the battery cannot provide sufficient power. Request roadside battery support in Coimbatore for a convenient solution when you need it.',
  'Safe and Professional Jump Starting',
  'Vehicle batteries and electrical systems need proper handling. We use compatible jump-start equipment and follow suitable safety procedures to help minimise electrical risks. If jump-starting is not appropriate, we recommend further battery inspection or replacement on the spot.',
  'Submit your service request - call or WhatsApp us and explain your vehicle starting problem.\nShare vehicle details - vehicle type, model, location and any known battery symptoms.\nConfirm service availability - our team checks the requirements and confirms whether assistance is available.\nBattery condition check - the battery and vehicle requirements are assessed before attempting a jump start.\nJump start assistance - suitable equipment and the recommended procedure are used to start your vehicle.\nFinal starting check - the technician confirms the vehicle starts and advises on any battery testing, charging or replacement needed.',
  '[{"question":"What is a vehicle jump starter service?","answer":"A vehicle jump starter service helps start a car or bike when its battery has too little power to turn the engine. Kiara Battery Clinic checks the vehicle and battery requirements first, then uses suitable jump-start equipment at your location in Coimbatore."},{"question":"Do you provide car and bike jump-start services in Coimbatore?","answer":"Yes. Jump-start assistance is available for compatible cars and bikes across Coimbatore, depending on the vehicle model, battery type and service coverage. Call or WhatsApp +91 90038 11107 to confirm availability for your vehicle."},{"question":"Can I request a jump starter service near me?","answer":"Yes. Share your current location and vehicle details by call or WhatsApp and our team will confirm whether jump-start assistance is available in your area, including Tatabad, Gandhipuram, RS Puram, Peelamedu, Saravanampatti, Ooty, Kotagiri, Pollachi and Tiruppur."},{"question":"How long does a jump-start service take?","answer":"The jump-start itself usually takes only a few minutes once the technician arrives. For calls within Coimbatore city a technician typically arrives within 30-60 minutes; the exact waiting time depends on your location, traffic conditions and service availability."},{"question":"Will jump-starting repair a completely dead battery?","answer":"No. Jump-starting can start a vehicle with a discharged battery, but it does not repair a damaged or worn-out battery. A battery test is recommended to find out whether charging or replacement is needed."},{"question":"Why will my vehicle not start even after a jump start?","answer":"The cause may be a faulty battery, starter motor, alternator, wiring issue or another electrical problem. If jump-starting does not work, further diagnosis by a qualified technician is recommended."},{"question":"Is jump-starting safe for modern vehicles?","answer":"Jump-starting is safe when the correct procedure and compatible equipment are used. Some modern vehicles have specific battery connection points and electrical requirements, so the manufacturer instructions should always be followed."},{"question":"What details should I provide when requesting jump-start assistance?","answer":"Share your vehicle type, model, location, battery symptoms and contact number. This helps our team assess your requirement and send the right assistance."},{"question":"What are your jump starter service hours?","answer":"Our service hours are Monday to Saturday, 9AM to 10PM. Call or WhatsApp +91 90038 11107 during these hours to request jump-start assistance."}]',
  'active',
  0,
  0
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `service` WHERE `token` = 'jump-starter-service');
